/**
 * Map backdrops — Natural Earth country outlines (public domain), grouped
 * into the business regions people use, that a zone can draw faintly inside
 * its box (`zone.backdrop`). Pieces and crop boxes are generated by
 * scripts/build-backdrops.ts; this module names the backdrops, maps region
 * names onto them, and hands them to the engine
 * (`TopologyDesigner.registerBackdrop`) in every render path.
 */
import {
  BACKDROP_PIECES,
  BACKDROP_REGIONS,
  type BackdropPieceName,
} from './backdrops.generated.js';

export const BACKDROP_NAMES = [
  'world',
  'na',
  'latam',
  'amer',
  'europe',
  'africa',
  'emea',
  'apac',
] as const;
export type BackdropName = (typeof BACKDROP_NAMES)[number];

export const BACKDROP_LABELS: Readonly<Record<BackdropName, string>> = {
  world: 'World',
  na: 'North America',
  latam: 'Latin America',
  amer: 'Americas (AMER)',
  europe: 'Europe',
  africa: 'Africa',
  emea: 'Europe, Middle East & Africa',
  apac: 'Asia-Pacific',
};

export function isBackdropName(v: unknown): v is BackdropName {
  return (
    typeof v === 'string' && (BACKDROP_NAMES as readonly string[]).includes(v)
  );
}

/** Region names people use → the backdrop that shows that region. */
const ALIASES: Record<string, BackdropName> = {
  world: 'world',
  global: 'world',
  na: 'na',
  noram: 'na',
  'north america': 'na',
  us: 'na',
  usa: 'na',
  canada: 'na',
  latam: 'latam',
  lata: 'latam',
  sa: 'latam',
  'south america': 'latam',
  'latin america': 'latam',
  'central america': 'latam',
  amer: 'amer',
  amers: 'amer',
  americas: 'amer',
  emea: 'emea',
  'middle east': 'emea',
  mea: 'emea',
  europe: 'europe',
  eu: 'europe',
  africa: 'africa',
  apac: 'apac',
  apj: 'apac',
  asia: 'apac',
  'asia pacific': 'apac',
  'asia-pacific': 'apac',
  anz: 'apac',
  oceania: 'apac',
};

/** The backdrop a region name refers to, or undefined when it names none. */
export function backdropForRegion(name: string): BackdropName | undefined {
  return ALIASES[name.trim().toLowerCase()];
}

/** A composed backdrop: crop box in the shared world frame, fill, borders. */
export interface ComposedBackdrop {
  x: number;
  y: number;
  w: number;
  h: number;
  /** Land fill. */
  d: string;
  /** Country borders and coasts (no artificial cut edges). */
  b: string;
}

/** Compose a backdrop from its generated pieces. */
export function composeBackdrop(name: BackdropName): ComposedBackdrop {
  const region = BACKDROP_REGIONS[name];
  const pieces = region.pieces.map(
    (p: BackdropPieceName) => BACKDROP_PIECES[p] as { d: string; b?: string },
  );
  return {
    x: region.x,
    y: region.y,
    w: region.w,
    h: region.h,
    d: pieces.map((p) => p.d).join(''),
    b: pieces.map((p) => p.b ?? p.d).join(''),
  };
}

interface BackdropEngine {
  registerBackdrop?(name: string, b: ComposedBackdrop): unknown;
}

let composed: Map<BackdropName, ComposedBackdrop> | null = null;

/** Register every backdrop with an engine (idempotent). */
export function registerBackdrops(engine: BackdropEngine | undefined): void {
  if (!engine?.registerBackdrop) return;
  composed ??= new Map(BACKDROP_NAMES.map((n) => [n, composeBackdrop(n)]));
  for (const [name, b] of composed) engine.registerBackdrop(name, b);
}
